    - 0: default, dynamicSmemBytes = SMEM_BYTES;
    - 1: also cudaLaunchAttributeClusterSchedulingPolicyPreference = cudaClusterSchedulingPolicySpread, dynamicSmemBytes = SMEM_BYTES;
    - 2: dynamicSmemBytes = SMEM_PAD.
  - TORCH_CHECKs:
    - B (= cache_seqlens.numel()) in 1..32; C in {4, 8, 16}; place in {0, 1, 2}; pre in {0, 1};
    - qkv bf16, 2-D, size(0) == 8B, size(1) >= 2304, stride(1) == 1;
    - positions and cache_loc int64, contiguous, numel 8B;
    - cache_seqlens int32, contiguous;
    - page_table int32, 2-D, size(0) == B, stride(1) == 1;
    - inv_freq fp32, contiguous, numel 32; k_scale and v_scale fp32;
    - k_cache / v_cache contiguous, 1-byte elements, [rows, 1, 2, 64];
    - out (B, 8, 1024) bf16 contiguous;
    - q8 e4m3 [8B, 16, 64] contiguous when pre == 0 (may be empty when pre == 1);
